// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address caller) public {
        vm.assume(caller != address(0) && caller != c.bank());
        uint initialBalance = caller.balance;
        vm.deal(caller, 10);
        vm.prank(caller);
        (bool success, ) = address(c).call{value: 10}(abi.encodeWithSignature("play()"));
        if (success) {
            uint finalBalance = caller.balance;
            // If payout occurred (random == 0 in reference), caller gets 9 (pot - fee = 10 - 1)
            // If no payout, caller gets 0 (pot remains in contract)
            assertTrue(finalBalance == initialBalance + 9 || finalBalance == initialBalance);
        } else {
            assertTrue(success); // always succeeds with exact 10 wei
        }
    }
}

